// Starter content (US-1.1): the Farm, Sea and Kitchen a fresh install opens with.
// web/data/starter.json is generated by tools/make-starter.mjs with readable placeholder ids;
// every load gets fresh ids and timestamps from env.
import { defaultSettings } from "../farm/snapshot.js";

/** "en-GB" → "en"; anything unusable → "en". */
export function baseLanguage(tag) {
  const base = String(tag ?? "").toLowerCase().split(/[-_]/)[0];
  return /^[a-z]{2,3}$/.test(base) ? base : "en";
}

/**
 * Turns the starter template into a fresh, valid Snapshot. Pure apart from env.
 * @param {import('../types.js').Snapshot} template
 * @param {import('../types.js').Env} env
 * @param {string} [lang]  e.g. navigator.language
 * @param {string} [appVersion]
 * @returns {import('../types.js').Snapshot}
 */
export function starterSnapshot(template, env, lang = "en", appVersion = "dev") {
  const ids = new Map();
  const id = (old) => {
    if (!ids.has(old)) ids.set(old, env.newId());
    return ids.get(old);
  };
  const now = env.now();
  const places = template.places.map((p) => ({
    ...p,
    id: id(p.id),
    pieces: p.pieces.map((piece) => ({ ...piece, id: env.newId(), stroke: piece.stroke.map(([x, y]) => [x, y]) })),
    thingOrder: p.thingOrder.map(id),
    createdAt: now,
    updatedAt: now,
  }));
  const things = template.things.map((t) => ({
    ...t,
    id: id(t.id),
    placeId: id(t.placeId),
    names: { ...t.names },
    outline: t.outline.map(([x, y]) => [x, y]),
    eyes: t.eyes.map((e) => ({ ...e })),
    legs: (t.legs ?? []).map((l) => ({ ...l })),
    motion: { ...t.motion, params: { ...t.motion.params } },
    cues: {},
    createdAt: now,
    updatedAt: now,
  }));
  const settings = defaultSettings(env, baseLanguage(lang));
  const farm = template.settings?.currentPlaceId ?? template.places[0]?.id;
  settings.currentPlaceId = farm ? id(farm) : null;
  return {
    formatVersion: template.formatVersion,
    minReaderFormat: template.minReaderFormat,
    appVersion,
    exportedAt: now,
    deviceId: env.deviceId,
    settings,
    places,
    things,
    clips: [],
  };
}

/** Fetches data/starter.json (relative to the document base) and returns a fresh Snapshot. */
export async function loadStarter(env, lang = "en", appVersion = "dev") {
  const res = await fetch("data/starter.json");
  if (!res.ok) throw new Error(`starter.json: HTTP ${res.status}`);
  return starterSnapshot(await res.json(), env, lang, appVersion);
}
